import type { Metadata } from "next"; import { ArticlePage } from "@/components/article-page"; import { Definition } from "@/components/ui"; export const metadata:Metadata={title:"BMI by Age",description:"How BMI is used differently for adults, older adults, children, and teenagers."}; export default function Page(){return <ArticlePage path="/bmi-by-age" title="BMI by age: adults, older adults, and children" description="The familiar BMI categories are for adults. Children and teenagers need age- and sex-specific percentiles."><Definition><strong>Answer:</strong> Adult BMI categories apply from age 18. For children and teens, clinicians use BMI-for-age percentiles based on growth charts.</Definition><h2>Adults</h2><p>From age 18, the standard category thresholds remain the same. A person’s health context can change over time, so the meaning of a BMI should always be individualized.</p><h2>Older adults</h2><p>Later life can bring loss of muscle mass and changes in appetite. Preventing unintentional weight loss, maintaining strength, and protecting mobility may take priority over pursuing a low BMI.</p><h2>Children and teenagers</h2><p>Growing bodies require a different approach. Parents should use paediatric growth charts and discuss concerns with a paediatric clinician rather than applying an adult calculator.</p></ArticlePage>}
